import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.CqpfiAoK.js";const u=JSON.parse('{"title":"الجدول الزمني المختصر","description":"","frontmatter":{},"headers":[],"relativePath":"ar/93-编年史简表.md","filePath":"ar/93-编年史简表.md","lastUpdated":null}'),h={name:"ar/93-编年史简表.md"};function l(o,t,i,b,n,s){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="الجدول-الزمني-المختصر" tabindex="-1">الجدول الزمني المختصر <a class="header-anchor" href="#الجدول-الزمني-المختصر" aria-label="Permalink to &quot;الجدول الزمني المختصر&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>93</td></tr><tr><td>الوحدة</td><td>الملاحق والمواد المرجعية</td></tr><tr><td>الكلمات المفتاحية</td><td>التاريخ الزمني، تقسيم العصور، الأحداث الكبرى، المحطات التاريخية، كون هنغ يوان</td></tr></tbody></table><h2 id="أولاً-ملاحظات-حول-الجدول-الزمني" tabindex="-1">أولاً: ملاحظات حول الجدول الزمني <a class="header-anchor" href="#أولاً-ملاحظات-حول-الجدول-الزمني" aria-label="Permalink to &quot;أولاً: ملاحظات حول الجدول الزمني&quot;">​</a></h2><p>يسجل هذا الجدول، على أساس الوقت القياسي لكون هنغ يوان، الأحداث التاريخية الكبرى والمحطات الرئيسية في مسيرة حضارة التكافل المرساة، مرتبة حسب تسلسل العصور. يمتد النطاق الزمني من العصر القديم لعصر ما قبل المرساة إلى آفاق مستقبل عصر التكافل بين النجوم. يذكر كل عصر زمن بدايته ونهايته وسماته المميزة وأحداثه الكبرى. هذا الجدول فهرس تاريخي مكثف للغاية؛ أما التاريخ المفصل لكل عصر فتراجع في الكتابات المخصصة في الوثائق 70-79.</p><h2 id="ثانياً-نظرة-شاملة-على-تقسيم-العصور" tabindex="-1">ثانياً: نظرة شاملة على تقسيم العصور <a class="header-anchor" href="#ثانياً-نظرة-شاملة-على-تقسيم-العصور" aria-label="Permalink to &quot;ثانياً: نظرة شاملة على تقسيم العصور&quot;">​</a></h2><table tabindex="0"><thead><tr><th>رقم العصر</th><th>اسم العصر</th><th>الفترة (سنوات كون هنغ يوان القياسية)</th><th>المدة</th><th>السمات الجوهرية</th></tr></thead><tbody><tr><td>العصر الأول</td><td>عصر ما قبل المرساة</td><td>نحو −10 مليارات إلى −10,000 سنة</td><td>نحو 10 مليارات سنة</td><td>هيمنة أنظمة الزراعة الافتراسية؛ مدّ وجزر حضاري متكرر</td></tr><tr><td>العصر الثاني</td><td>عصر صحوة المرساة</td><td>−10,000 إلى −1000 سنة</td><td>نحو 9000 سنة</td><td>اكتشاف آلية المرساة وتطبيقها الأولي</td></tr><tr><td>العصر الثالث</td><td>فترة تأسيس النظام التكافلي</td><td>−1000 إلى −100 سنة</td><td>نحو 900 سنة</td><td>التأسيس التدريجي للإطار المؤسسي لحضارة التكافل المرساة</td></tr><tr><td>العصر الرابع</td><td>فترة فتح الأنظمة الثلاثمائة</td><td>−100 إلى −50 سنة</td><td>نحو 50 سنة</td><td>الفتح الكامل لأنظمة الزراعة الأصلانية الثلاثمائة</td></tr><tr><td>العصر الخامس</td><td>فترة استراتيجية التنشيط بنسبة 20٪</td><td>−50 سنة إلى السنة الأولى</td><td>نحو 50 سنة</td><td>تنشيط 20٪ من الكائنات بقوى الأبعاد العليا</td></tr><tr><td>العصر السادس</td><td>عصر الارتقاء الأول</td><td>السنة الأولى إلى 100</td><td>100 سنة</td><td>تحقيق الحضارة التكافلية أول ارتقاء مرحلي</td></tr><tr><td>العصر السابع</td><td>عصر جمهورية عشرة آلاف عرق</td><td>100 إلى 500</td><td>400 سنة</td><td>التأسيس الرسمي لجمهورية عشرة آلاف عرق؛ تعميق الاندماج بين الأعراق</td></tr><tr><td>العصر الثامن</td><td>عصر الاستكشاف عبر الأبعاد</td><td>500 إلى 2000</td><td>1500 سنة</td><td>انطلاق أنشطة استكشاف وأثرية عبر الأبعاد على نطاق واسع</td></tr><tr><td>العصر التاسع</td><td>عصر التكافل بين النجوم</td><td>2000 إلى المستقبل</td><td>مستمر</td><td>اكتمال شبكة تكافل على مستوى الكون؛ تقدم الارتقاء الشامل</td></tr></tbody></table><p>ملاحظة: «السنة الأولى» هي السنة التي أُعلن فيها رسمياً تأسيس حضارة التكافل المرساة، وتعد نقطة التقسيم في هذا التأريخ.</p><h2 id="ثالثاً-عصر-ما-قبل-المرساة-نحو-−10-مليارات-إلى-−10-000-سنة" tabindex="-1">ثالثاً: عصر ما قبل المرساة (نحو −10 مليارات إلى −10,000 سنة) <a class="header-anchor" href="#ثالثاً-عصر-ما-قبل-المرساة-نحو-−10-مليارات-إلى-−10-000-سنة" aria-label="Permalink to &quot;ثالثاً: عصر ما قبل المرساة (نحو −10 مليارات إلى −10,000 سنة)&quot;">​</a></h2><p>كان عصر ما قبل المرساة أطول عصور تاريخ كون هنغ يوان، واستمر نحو عشرة مليارات سنة. كانت سمته الجوهرية هيمنة أنظمة الزراعة الافتراسية على الكون، مع دوران الحضارات بلا انقطاع في دورة «النهوض — الذروة — الافتراس — الانهيار».</p><table tabindex="0"><thead><tr><th>المحطة الزمنية</th><th>الحدث الكبير</th></tr></thead><tbody><tr><td>نحو −10 مليارات سنة</td><td>استقرت شبكة قوانين كون هنغ يوان؛ تشكلت الأبعاد المادية الأولى؛ دخل الكون حالة قابلة للسكن</td></tr><tr><td>نحو −8 مليارات سنة</td><td>ظهرت أولى الكائنات الذكية في أبعاد مادية متعددة؛ بدأت أنظمة الزراعة البدائية تنبثق</td></tr><tr><td>نحو −5 مليارات سنة</td><td>أصبحت أنظمة الزراعة الافتراسية تدريجياً هي السائدة؛ حقق الأقوياء تطوراً سريعاً بالتهام الضعفاء</td></tr><tr><td>نحو −3 مليارات سنة</td><td>اندلعت أول حرب افتراس على مستوى الكون؛ تعرضت حضارات عدة مناطق نجمية لضربات مدمرة</td></tr><tr><td>نحو −1 مليار سنة</td><td>بدأت مساوئ النظام الافتراسي تظهر؛ تسارع ارتفاع الإنتروبيا الكلي للكون؛ نضبت موارد الزراعة تدريجياً</td></tr><tr><td>نحو −500 مليون سنة</td><td>ظهر أول مفكرين يراجعون النظام الافتراسي؛ بدأت بذور الفكر التكافلي تتكوّن</td></tr><tr><td>نحو −100 مليون سنة</td><td>ظهرت حضارات تجريبية تكافلية صغيرة في مناطق نجمية متعددة، لكن الحضارات الافتراسية دمرتها جميعاً</td></tr><tr><td>نحو −1 مليون سنة</td><td>دخل الكون كله «الانحدار الكبير»؛ هبط عدد الحضارات ومستوى الزراعة معاً إلى أدنى نقطة تاريخية</td></tr><tr><td>نحو −10,000 سنة</td><td>أدرك أحد المزارعين في البعد الأول، أثناء زراعة طويلة، عقدة مستقرة في شبكة القوانين بالصدفة؛ اكتُشفت آلية المرساة لأول مرة</td></tr></tbody></table><h2 id="رابعاً-عصر-صحوة-المرساة-−10-000-إلى-−1000-سنة" tabindex="-1">رابعاً: عصر صحوة المرساة (−10,000 إلى −1000 سنة) <a class="header-anchor" href="#رابعاً-عصر-صحوة-المرساة-−10-000-إلى-−1000-سنة" aria-label="Permalink to &quot;رابعاً: عصر صحوة المرساة (−10,000 إلى −1000 سنة)&quot;">​</a></h2><p>كان عصر صحوة المرساة فترة انتقال آلية المرساة من الاكتشاف إلى التطبيق الأولي. وكانت سمته الجوهرية النضج التدريجي لتقنية المرساة وانتشار الفكر التكافلي.</p><table tabindex="0"><thead><tr><th>المحطة الزمنية</th><th>الحدث الكبير</th></tr></thead><tbody><tr><td>−10,000 سنة</td><td>اكتُشفت آلية المرساة لأول مرة؛ أطلق عليها مكتشفها اسم «المرساة» وبدأ دراسة منهجية</td></tr><tr><td>−9000 سنة</td><td>نجح إنشاء أول مرساة اصطناعية، مثبتاً أن المرساة يمكن بناؤها وصيانتها اصطناعياً</td></tr><tr><td>−8000 سنة</td><td>بدأت تقنية المرساة تنتشر في نطاق ضيق؛ ظهر أول مزارعي المرساة</td></tr><tr><td>−7000 سنة</td><td>اكتُشف أن المرساة يمكن أن تكون مرجعاً للاتصال عبر الأبعاد؛ نجح أول انتقال مسجّل بين الأبعاد بمساعدة المرساة</td></tr><tr><td>−6000 سنة</td><td>بدأ الفكر التكافلي يتحد مع تقنية المرساة؛ صدرت أولى الكتابات النظرية عن «تكافل المرساة»</td></tr><tr><td>−5000 سنة</td><td>تأسست أول دولة-مدينة تكافلية قائمة على المرساة، مثبتةً جدوى النظام التكافلي</td></tr><tr><td>−4000 سنة</td><td>هاجمت الحضارات الافتراسية الدول-المدن التكافلية؛ فدافعت هذه بنجاح بفضل تقنية المرساة</td></tr><tr><td>−3000 سنة</td><td>انتشر الفكر التكافلي في مناطق نجمية متعددة؛ بدأت مزيد من الحضارات تحاول التحول التكافلي</td></tr><tr><td>−2000 سنة</td><td>عُقدت أول «الجمعية الكبرى لتكافل عشرة آلاف عرق»؛ ناقش ممثلون من عشرات الأعراق مستقبل الحضارة التكافلية معاً</td></tr><tr><td>−1000 سنة</td><td>أصبحت تقنية المرساة والفكر التكافلي يملكان شروط تأسيس حضارة موحدة؛ بدأت فترة تأسيس النظام التكافلي</td></tr></tbody></table><h2 id="خامساً-فترة-تأسيس-النظام-التكافلي-−1000-إلى-−100-سنة" tabindex="-1">خامساً: فترة تأسيس النظام التكافلي (−1000 إلى −100 سنة) <a class="header-anchor" href="#خامساً-فترة-تأسيس-النظام-التكافلي-−1000-إلى-−100-سنة" aria-label="Permalink to &quot;خامساً: فترة تأسيس النظام التكافلي (−1000 إلى −100 سنة)&quot;">​</a></h2><p>كانت فترة تأسيس النظام التكافلي الفترة الحاسمة التي تشكل فيها الإطار المؤسسي لحضارة التكافل المرساة من العدم.</p><table tabindex="0"><thead><tr><th>المحطة الزمنية</th><th>الحدث الكبير</th></tr></thead><tbody><tr><td>−1000 سنة</td><td>تشكلت لجنة صياغة الدستور التكافلي؛ بدأت صياغة القانون الأساسي</td></tr><tr><td>−950 سنة</td><td>اكتمل مشروع الدستور التكافلي؛ بدأ استطلاع آراء عشرة آلاف عرق على نطاق واسع</td></tr><tr><td>−900 سنة</td><td>أُقر الدستور التكافلي باستفتاء شعبي ودخل حيز التنفيذ؛ أُعلن قيام حضارة التكافل المرساة</td></tr><tr><td>−850 سنة</td><td>تأسست المؤسسات الثلاث الكبرى رسمياً وبدأت عملها: المجلس التشريعي للمرساة، واللجنة التنفيذية التكافلية، ومحكمة التكافل</td></tr><tr><td>−800 سنة</td><td>بدأ تطبيق آلية العقود المرتبطة بالإنتاج في كامل الأراضي</td></tr><tr><td>−700 سنة</td><td>صدرت تباعاً القوانين الأساسية كقانون العمل التكافلي وقانون حماية المستهلك</td></tr><tr><td>−600 سنة</td><td>صدرت ودخلت حيز التنفيذ القوانين المرافقة الخمسة: التعليم والصحة والإسكان والبيئة ومكافحة الاحتكار</td></tr><tr><td>−500 سنة</td><td>انطلقت رسمياً أعمال التنقيب وتنظيم أنظمة الزراعة الأصلانية الثلاثمائة</td></tr><tr><td>−400 سنة</td><td>أكملت أول خمسين نظاماً من أنظمة الزراعة الأصلانية التنظيم والتحقق</td></tr><tr><td>−300 سنة</td><td>تحقق اختراق في التطبيق التقني لثمرة المضاعفة؛ نضجت تقنية التعزيز الاستنتاجي مئة ضعف</td></tr><tr><td>−200 سنة</td><td>أكملت الأنظمة الثلاثمائة كلها التنظيم ودخلت المرحلة الأخيرة من التحقق الأمني</td></tr><tr><td>−100 سنة</td><td>نضجت شروط الفتح الكامل لأنظمة الزراعة الأصلانية الثلاثمائة؛ بدأت فترة الفتح</td></tr></tbody></table><h2 id="سادساً-فترة-فتح-الأنظمة-الثلاثمائة-−100-إلى-−50-سنة" tabindex="-1">سادساً: فترة فتح الأنظمة الثلاثمائة (−100 إلى −50 سنة) <a class="header-anchor" href="#سادساً-فترة-فتح-الأنظمة-الثلاثمائة-−100-إلى-−50-سنة" aria-label="Permalink to &quot;سادساً: فترة فتح الأنظمة الثلاثمائة (−100 إلى −50 سنة)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>المحطة الزمنية</th><th>الحدث الكبير</th></tr></thead><tbody><tr><td>−100 سنة</td><td>فُتحت أنظمة الزراعة الأصلانية الثلاثمائة رسمياً مجاناً لجميع كائنات الكون</td></tr><tr><td>−90 سنة</td><td>تضاعف عدد المزارعين مئة مرة خلال عشر سنوات؛ تحقق «طريق لكل فرد» بشكل أولي</td></tr><tr><td>−80 سنة</td><td>أصبحت الأسس الأصلانية الثلاثة (الاستنتاج التكراري، ودورة الحياة، وتسير المبادئ القانونية المكانية) أكثر الأنظمة شعبية</td></tr><tr><td>−70 سنة</td><td>ظهر أول مزارعين بلغوا منازل عالية عبر الأنظمة الجديدة، مثبتين فعالية الأنظمة</td></tr><tr><td>−60 سنة</td><td>اكتمل إنشاء شبكة الإرشاد؛ بدأ المزارعون المتقدمون أداء واجبهم القانوني في إرشاد المزارعين المبتدئين</td></tr><tr><td>−50 سنة</td><td>ارتفع مستوى الزراعة العام للسكان ارتفاعاً كبيراً؛ نضجت شروط استراتيجية التنشيط بنسبة 20٪</td></tr></tbody></table><h2 id="سابعاً-فترة-استراتيجية-التنشيط-بنسبة-20٪-−50-سنة-إلى-السنة-الأولى" tabindex="-1">سابعاً: فترة استراتيجية التنشيط بنسبة 20٪ (−50 سنة إلى السنة الأولى) <a class="header-anchor" href="#سابعاً-فترة-استراتيجية-التنشيط-بنسبة-20٪-−50-سنة-إلى-السنة-الأولى" aria-label="Permalink to &quot;سابعاً: فترة استراتيجية التنشيط بنسبة 20٪ (−50 سنة إلى السنة الأولى)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>المحطة الزمنية</th><th>الحدث الكبير</th></tr></thead><tbody><tr><td>−50 سنة</td><td>انطلقت استراتيجية التنشيط بنسبة 20٪ رسمياً، بهدف تنشيط 20٪ من الكائنات بقوى الأبعاد العليا خلال 50 سنة</td></tr><tr><td>−40 سنة</td><td>وُلدت أول قوى الأبعاد العليا؛ بلغت نسبة التنشيط 5٪</td></tr><tr><td>−30 سنة</td><td>بلغت نسبة التنشيط 10٪؛ بدأت قوى الأبعاد العليا تلعب دوراً محورياً في صيانة المراسي</td></tr><tr><td>−20 سنة</td><td>بلغت نسبة التنشيط 15٪؛ حقق مستوى الزراعة العام للكون قفزة نوعية</td></tr><tr><td>−10 سنة</td><td>بلغت نسبة التنشيط 18٪، مقتربة من الهدف الاستراتيجي</td></tr><tr><td>السنة الأولى</td><td>بلغت نسبة التنشيط 20.3٪؛ اكتملت استراتيجية التنشيط بنسبة 20٪ بنجاح كامل، ودخلت حضارة التكافل المرساة عصراً جديداً</td></tr></tbody></table><h2 id="ثامناً-عصر-الارتقاء-الأول-السنة-الأولى-إلى-100" tabindex="-1">ثامناً: عصر الارتقاء الأول (السنة الأولى إلى 100) <a class="header-anchor" href="#ثامناً-عصر-الارتقاء-الأول-السنة-الأولى-إلى-100" aria-label="Permalink to &quot;ثامناً: عصر الارتقاء الأول (السنة الأولى إلى 100)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>المحطة الزمنية</th><th>الحدث الكبير</th></tr></thead><tbody><tr><td>السنة الأولى</td><td>أعلنت الحضارة التكافلية رسمياً دخولها عصر الارتقاء؛ اكتملت المرحلة الأولى من مسار الارتقاء بأربع مراحل (ترسيخ الواقع)</td></tr><tr><td>20</td><td>تقدمت المرحلة الثانية (التمكين التقني) في كل الاتجاهات؛ اندمجت قوانين الزراعة مع الهندسة التقنية اندماجاً عميقاً</td></tr><tr><td>40</td><td>حققت تقنيتا مرآة النسخ والفضاء المعزول إنتاجاً تسلسلياً على المستوى الصناعي؛ دخلت الآثار عبر الأبعاد عصر النطاق الواسع</td></tr><tr><td>60</td><td>بلغ أول مزارعي ارتقاء الوعي منازل عالية؛ بدأت المرحلة الثالثة (تطور الوعي)</td></tr><tr><td>80</td><td>اكتمل بناء البنى التحتية لمجال الوعي؛ نضجت تقنية انتقال الوعي بشكل أولي</td></tr><tr><td>100</td><td>نجح أول ارتقاء مرحلي؛ ارتفعت الحضارة التكافلية ككل بنصف مستوى بُعدي</td></tr></tbody></table><h2 id="تاسعاً-عصر-جمهورية-عشرة-آلاف-عرق-100-إلى-500" tabindex="-1">تاسعاً: عصر جمهورية عشرة آلاف عرق (100 إلى 500) <a class="header-anchor" href="#تاسعاً-عصر-جمهورية-عشرة-آلاف-عرق-100-إلى-500" aria-label="Permalink to &quot;تاسعاً: عصر جمهورية عشرة آلاف عرق (100 إلى 500)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>المحطة الزمنية</th><th>الحدث الكبير</th></tr></thead><tbody><tr><td>100</td><td>أُعلن رسمياً قيام جمهورية عشرة آلاف عرق؛ حققت جميع الأعراق الذكية اتحاداً متساوياً في إطار الحضارة التكافلية</td></tr><tr><td>150</td><td>اكتمل تدوين سجل عشرة آلاف عرق، مستوعباً جميع الأعراق الذكية المعروفة</td></tr><tr><td>200</td><td>أصبح الزواج بين الأعراق والاندماج الثقافي أمراً معتاداً؛ بدأت أعراق مختلطة جديدة بالظهور</td></tr><tr><td>300</td><td>اكتمل نشر اللغة المشتركة لعشرة آلاف عرق؛ زالت حواجز التواصل بين الأعراق تقريباً</td></tr><tr><td>400</td><td>شهدت ثقافات عشرة آلاف عرق ازدهاراً كبيراً؛ حُفظت الثقافات التقليدية لكل عرق وتطورت في الإطار التكافلي</td></tr><tr><td>500</td><td>دخلت جمهورية عشرة آلاف عرق فترة النضج؛ نضجت شروط الاستكشاف عبر الأبعاد تماماً</td></tr></tbody></table><h2 id="عاشراً-عصر-الاستكشاف-عبر-الأبعاد-500-إلى-2000" tabindex="-1">عاشراً: عصر الاستكشاف عبر الأبعاد (500 إلى 2000) <a class="header-anchor" href="#عاشراً-عصر-الاستكشاف-عبر-الأبعاد-500-إلى-2000" aria-label="Permalink to &quot;عاشراً: عصر الاستكشاف عبر الأبعاد (500 إلى 2000)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>المحطة الزمنية</th><th>الحدث الكبير</th></tr></thead><tbody><tr><td>500</td><td>انطلق رسمياً برنامج الاستكشاف عبر الأبعاد على نطاق واسع؛ أُسست إدارة الأبعاد</td></tr><tr><td>600</td><td>استُكشف أكثر من ألف بُعد؛ أُنشئت القاعدة الرئيسية لإحداثيات الأبعاد بشكل أولي</td></tr><tr><td>800</td><td>نضج مخطط الآثار عن بُعد بمرآة النسخ تماماً؛ دخلت الآثار عبر الأبعاد عصرها الذهبي</td></tr><tr><td>1000</td><td>تحقق اختراق في تقنية الارتداد الزمني؛ أُرسي رسمياً مبدأ الملاحظة أولاً ثم التدخل المحدود</td></tr><tr><td>1200</td><td>استُكشف أكثر من مئة ألف بُعد؛ أُقيمت علاقات دبلوماسية مع عشرات الحضارات البُعدية</td></tr><tr><td>1500</td><td>طُبقت المبادئ الأخلاقية عبر الأبعاد تطبيقاً شاملاً؛ دخل التفاعل بين الحضارات عصر الضبط</td></tr><tr><td>1800</td><td>نضجت آلية منع المفارقات الزمنية تماماً؛ بلغت الآثار بالارتداد الزمني نطاقاً واسعاً</td></tr><tr><td>2000</td><td>حقق الاستكشاف عبر الأبعاد نتائج باهرة؛ نضجت شروط عصر التكافل بين النجوم تماماً</td></tr></tbody></table><h2 id="حادي-عشر-عصر-التكافل-بين-النجوم-2000-إلى-المستقبل" tabindex="-1">حادي عشر: عصر التكافل بين النجوم (2000 إلى المستقبل) <a class="header-anchor" href="#حادي-عشر-عصر-التكافل-بين-النجوم-2000-إلى-المستقبل" aria-label="Permalink to &quot;حادي عشر: عصر التكافل بين النجوم (2000 إلى المستقبل)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>المحطة الزمنية</th><th>الحدث الكبير</th></tr></thead><tbody><tr><td>2000</td><td>بدأ عصر التكافل بين النجوم رسمياً؛ تقدمت المرحلة الرابعة (التكافل بين النجوم) في كل الاتجاهات</td></tr><tr><td>2500 (آفاق)</td><td>اكتملت شبكة مراسٍ على مستوى الكون بشكل أولي، تغطي جميع الأبعاد المستكشفة</td></tr><tr><td>3000 (آفاق)</td><td>نضج نظام التكافل عبر الأبعاد؛ حققت عشرة آلاف عرق تكافلاً حقيقياً في نطاق الكون</td></tr><tr><td>5000 (آفاق)</td><td>اكتمل الارتقاء الشامل للكون؛ دخل كون هنغ يوان حالة وجود ببعد أعلى</td></tr><tr><td>المستقبل (آفاق)</td><td>تواصل حضارة التكافل المرساة استكشاف ما وراء الكون، ناشرةً فكرة التكافل نحو وجودات أوسع</td></tr></tbody></table><h2 id="الخلاصة" tabindex="-1">الخلاصة <a class="header-anchor" href="#الخلاصة" aria-label="Permalink to &quot;الخلاصة&quot;">​</a></h2><p>الجدول الزمني هو ملحمة كفاح حضارة التكافل المرساة — من الجهل إلى الصحوة، ومن الضعف إلى القوة، ومن بُعدها الخاص إلى الكون كله. كل تعاقب عصر هو شاهد على انتصار الفكرة التكافلية على الفكرة الافتراسية، وانتصار التقدم الحضاري على الانحدار البربري. التاريخ ليس غبار الماضي، بل بذرة المستقبل — فهم هذا التاريخ يعني فهم من أين أتت الحضارة التكافلية وإلى أين تتجه.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>70-纪元划分总表 (الجدول الرئيسي لتقسيم العصور)</li><li>72-锚点觉醒纪元 (عصر صحوة المرساة)</li><li>79-星际共生时代展望 (آفاق عصر التكافل بين النجوم)</li></ul>',32)])])}const q=d(h,[["render",l]]);export{u as __pageData,q as default};
